67	
68	@RestController
69	@CrossOrigin(exposedHeaders = "errors, content-type")
70	@RequestMapping("/api")
71	public class OwnerRestControllerV1 implements OwnersApi {
72	
73	    /**
74	     * Basic syntactic email check: a non-empty local part, an '@', and a domain containing at least
75	     * one dot, with no whitespace anywhere. Deliberately permissive but requires the essential shape.
76	     */
77	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
78	
79	    /**
80	     * Domains known to hand out disposable/throwaway mailboxes. An owner whose email domain is on
81	     * this blocklist is rejected: such addresses cannot be relied on for contacting the owner.
82	     */
83	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS =
84	        Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
85	
86	    /** Dedicated audit logger; create side-effects are recorded here so they can be observed independently. */
87	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
88	
89	    private final ClinicService clinicService;
90	
91	    private final OwnerMapper ownerMapper;
92	
93	    private final PetMapper petMapper;
94	
95	    private final VisitMapper visitMapper;
96	
97	    public OwnerRestControllerV1(ClinicService clinicService,
98	                                 OwnerMapper ownerMapper,
99	                                 PetMapper petMapper,
100	                                 VisitMapper visitMapper) {
101	        this.clinicService = clinicService;
102	        this.ownerMapper = ownerMapper;
103	        this.petMapper = petMapper;
104	        this.visitMapper = visitMapper;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        List<OwnerDto> ownerDtos = owners.stream()
120	            .map(this::toOwnerDtoWithBulkWarning)
121	            .toList();
122	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
133	    }
134	
135	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
136	    @Override
137	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
138	        List<String> missingFields = new ArrayList<>();
139	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
140	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
141	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
142	        requireNonBlank(missingFields, "address", normalizedAddress);
143	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
144	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
145	        if (!missingFields.isEmpty()) {
146	            throw new MissingRequiredFieldsException(missingFields);
147	        }
148	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
149	        validateRegistrationDate(ownerFieldsDto.getRegistrationDate());
150	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
151	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
152	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
153	        requireDailyLimitNotReached(registrationDate);
154	        requireCityBelowCapacity(ownerFieldsDto.getCity());
155	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
156	        ownerFieldsDto.setTelephone(normalizedTelephone);
157	        if (ownerFieldsDto.getEmail() != null) {
158	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
159	        }
160	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
161	        HttpHeaders headers = new HttpHeaders();
162	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
163	        owner.setAddress(normalizedAddress);
164	        owner.setRegistrationDate(registrationDate);
165	        owner.setCustomerCode(buildCustomerCode(owner, normalizedTelephone));
166	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
