274	    /**
275	     * Builds the owner's customer code as {@code '<REGION>-<HASH8>'}, where {@code REGION} is the
276	     * region derived from the owner's postcode (falling back to its city, else {@code 'UNKNOWN'}) via
277	     * {@link OwnerMapper#toRegion}, and {@code HASH8} is the first 8 upper-case hex characters of the
278	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}).
279	     *
280	     * <p>When the computed code collides with an existing owner's {@code customerCode}, it is
281	     * de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that makes it
282	     * unique (e.g. {@code NSW-1A2B3C4D-2}); the de-duplicated code is returned. Absent a collision the
283	     * base region-and-hash code is returned unchanged.
284	     *
285	     * @param owner the owner being created, with its region-determining postcode and city populated
286	     * @param normalizedTelephone the owner's normalized (E.164) telephone, hashed with the last name
287	     * @return the (de-duplicated) region-and-hash customer code for the owner being created
288	     */
289	    private String buildCustomerCode(Owner owner, String normalizedTelephone) {
290	        String region = ownerMapper.toRegion(owner);
291	        String hash8 = sha256Hex8(normalizedTelephone + owner.getLastName());
292	        String baseCode = region + "-" + hash8;
293	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
294	            .map(Owner::getCustomerCode)
295	            .filter(java.util.Objects::nonNull)
296	            .collect(java.util.stream.Collectors.toSet());
297	        if (!existingCodes.contains(baseCode)) {
298	            return baseCode;
299	        }
300	        int n = 2;
301	        while (existingCodes.contains(baseCode + "-" + n)) {
302	            n++;
303	        }
304	        return baseCode + "-" + n;
305	    }
306	
307	    /**
308	     * Returns the first 8 upper-case hex characters of the SHA-256 digest of {@code value}'s UTF-8
309	     * bytes. Deterministic, so the same input always yields the same 8-character hash.
310	     */
311	    private static String sha256Hex8(String value) {
312	        try {
313	            byte[] digest = MessageDigest.getInstance("SHA-256")
314	                .digest(value.getBytes(StandardCharsets.UTF_8));
315	            StringBuilder sb = new StringBuilder();
316	            for (byte b : digest) {
317	                sb.append(String.format("%02X", b));
318	            }
319	            return sb.substring(0, 8);
320	        }
321	        catch (NoSuchAlgorithmException e) {
322	            throw new IllegalStateException("SHA-256 not available", e);
323	        }
324	    }
