352	    /**
353	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
354	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
355	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
356	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
357	     * {@code "+61412345678"}.
358	     *
359	     * @param telephone the raw telephone value from the request
360	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
361	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
362	     */
363	    private static String normalizeTelephone(String telephone) {
364	        String e164 = toE164(telephone);
365	        if (e164 == null) {
366	            throw new InvalidFieldValueException("telephone",
367	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
368	        }
369	        return e164;
370	    }
371	
372	    /**
373	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
374	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
375	     * owners' stored numbers when detecting duplicates.
376	     */
377	    private static String toE164(String telephone) {
378	        if (telephone == null) {
379	            return null;
380	        }
381	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
382	        String digits;
383	        if (cleaned.startsWith("+")) {
384	            digits = cleaned.substring(1);
385	        } else {
386	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
387	            digits = "61" + national;
388	        }
389	        if (!digits.matches("[0-9]{8,15}")) {
390	            return null;
391	        }
392	        if (!hasValidNationalLength(digits)) {
393	            return null;
394	        }
395	        return "+" + digits;
396	    }
397	
398	    /**
399	     * Checks the national-number length against the country code for the country codes that pin one.
400	     * A {@code '+61'} (Australia) number must carry exactly 9 national digits and a {@code '+1'}
401	     * (NANP) number exactly 10; every other country code is accepted on the general 8-to-15-digit
402	     * rule alone. {@code digits} is the E.164 digit string without the leading {@code '+'}.
403	     */
404	    private static boolean hasValidNationalLength(String digits) {
405	        if (digits.startsWith("61")) {
406	            return digits.length() - 2 == 9;
407	        }
408	        if (digits.startsWith("1")) {
409	            return digits.length() - 1 == 10;
410	        }
411	        return true;
412	    }
