414	    /**
415	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
416	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
417	     *
418	     * @param email the raw email value from the request (already known to be non-null)
419	     * @return the lower-cased email to be stored and returned
420	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
421	     */
422	    private static String normalizeEmail(String email) {
423	        String trimmed = email.trim();
424	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
425	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
426	        }
427	        String canonical = trimmed.toLowerCase(Locale.ROOT);
428	        String domain = canonical.substring(canonical.indexOf('@') + 1);
429	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
430	            throw new InvalidFieldValueException("email", "Email must not use a disposable-domain address");
431	        }
432	        return canonical;
433	    }
