523	    /**
524	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
525	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
526	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
527	     * is recorded on the next business day, and every value derived from the registration date uses the
528	     * adjusted date.
529	     *
530	     * @param date the effective registration date (supplied or defaulted), never {@code null}
531	     * @return the same date, or the next Monday when {@code date} is a weekend
532	     */
533	    private static LocalDate toBusinessDay(LocalDate date) {
534	        DayOfWeek day = date.getDayOfWeek();
535	        if (day == DayOfWeek.SATURDAY) {
536	            return date.plusDays(2);
537	        }
538	        if (day == DayOfWeek.SUNDAY) {
539	            return date.plusDays(1);
540	        }
541	        return date;
542	    }
