544	    /** Matches a well-formed postcode: exactly four decimal digits. */
545	    private static final Pattern POSTCODE_PATTERN = Pattern.compile("^[0-9]{4}$");
546	
547	    /**
548	     * Fixed region-to-postcode range table: each region admits an inclusive 4-digit range
549	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). Regions are derived
550	     * from the owner's city via {@link OwnerMapper#CITY_REGION}; a city with no known region is not
551	     * present here and accepts any well-formed postcode.
552	     */
553	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
554	        "NSW", new int[] {2000, 2099},
555	        "VIC", new int[] {3000, 3099},
556	        "QLD", new int[] {4000, 4099});
557	
558	    /**
559	     * Validates an owner's optional {@code postcode}. When absent nothing is checked (postcode is
560	     * optional, so the request contract stays backward-compatible). When present it must be exactly
561	     * four digits and, for a city whose region is known, fall within that region's inclusive range
562	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099); a city with no known region accepts any 4-digit
563	     * postcode. A malformed or out-of-range value is rejected with a 400.
564	     *
565	     * @param postcode the raw postcode from the request (may be {@code null} when not supplied)
566	     * @param city the owner's city, used to look up the region whose range constrains the postcode
567	     * @throws InvalidFieldValueException if the postcode is present but malformed or out of range
568	     */
569	    private void validatePostcode(String postcode, String city) {
570	        if (postcode == null) {
571	            return;
572	        }
573	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
574	            throw new InvalidFieldValueException("postcode", "Postcode must be exactly four digits");
575	        }
576	        String region = OwnerMapper.CITY_REGION.getOrDefault(city, "UNKNOWN");
577	        int[] range = REGION_POSTCODES.get(region);
578	        if (range == null) {
579	            return;
580	        }
581	        int value = Integer.parseInt(postcode);
582	        if (value < range[0] || value > range[1]) {
583	            throw new InvalidFieldValueException("postcode",
584	                "Postcode must be valid for the city's region " + region);
585	        }
586	    }
