588	    /**
589	     * Validates an owner's optional {@code registrationDate}. When absent nothing is checked (the
590	     * date defaults to the server date). When present it must not be later than the current server
591	     * date: a registration cannot be recorded in the future, so a future date is rejected with a 400.
592	     *
593	     * @param registrationDate the supplied registration date (may be {@code null} when not supplied)
594	     * @throws InvalidFieldValueException if the supplied date is later than the server date
595	     */
596	    private void validateRegistrationDate(LocalDate registrationDate) {
597	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
598	            throw new InvalidFieldValueException("registrationDate",
599	                "Registration date must not be later than the current date");
600	        }
601	    }
