624	     */
625	    private void requireUniqueIdentity(Owner owner) {
626	        String identityKey = ownerMapper.toIdentityKey(owner);
627	        boolean taken = this.clinicService.findAllOwners().stream()
628	            .map(ownerMapper::toIdentityKey)
629	            .anyMatch(identityKey::equals);
