635	    /**
636	     * Rejects the request when the incoming owner would join an existing household, unless the owner
637	     * has opted in via {@code sharesHousehold}. Because the household is keyed on {@code householdId}
638	     * (the computed hash of the normalized last name and postcode), any existing owner carrying the
639	     * same {@code householdId} is a member of the same household, so a second such owner is a
640	     * household duplicate. Setting {@code sharesHousehold} bypasses this block, declaring the owner a
641	     * genuine additional member of that household. An owner with no {@code householdId} (no postcode,
642	     * so no household key) is never a household duplicate.
643	     *
644	     * @param owner the incoming owner, with its computed {@code householdId} already populated
645	     * @param sharesHousehold whether the request opted in to joining an existing household
646	     * @throws DuplicateIdentityException if the household already exists and the owner did not opt in
647	     */
648	    private void requireNoHouseholdDuplicate(Owner owner, boolean sharesHousehold) {
649	        if (sharesHousehold) {
650	            return;
651	        }
652	        String householdId = owner.getHouseholdId();
653	        if (householdId == null) {
654	            return;
655	        }
656	        boolean householdExists = this.clinicService.findAllOwners().stream()
657	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
658	        if (householdExists) {
659	            throw new DuplicateIdentityException(ownerMapper.toIdentityKey(owner));
