673	     * @param owner the incoming owner, with its computed {@code householdId} and telephone populated
674	     * @param sharesHousehold whether the request opted in as a declared household member
675	     */
676	    private void markPossibleDuplicate(Owner owner, boolean sharesHousehold) {
677	        owner.setPossibleDuplicate(false);
678	        owner.setPossibleDuplicateOf(null);
679	        if (sharesHousehold) {
680	            return;
681	        }
682	        String householdId = owner.getHouseholdId();
683	        if (householdId == null) {
684	            return;
685	        }
686	        String telephone = owner.getTelephone();
687	        this.clinicService.findAllOwners().stream()
688	            .filter(existing -> householdId.equals(existing.getHouseholdId())
689	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
690	            .min(java.util.Comparator.comparing(Owner::getId))
691	            .ifPresent(match -> {
692	                owner.setPossibleDuplicate(true);
693	                owner.setPossibleDuplicateOf(match.getId());
694	            });
695	    }
696	
697	    /**
698	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
699	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
700	     * comparisons are case-insensitive.
701	     */
702	    private static String normalizeForHousehold(String value) {
703	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
704	    }
705	
706	    /**
707	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
708	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
709	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
710	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
711	     * value normalizes to the empty string, so the required-field check rejects an address that is
712	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
713	     *
714	     * @param address the raw address value from the request (may be {@code null})
715	     * @return the normalized address, or the empty string when blank after normalization
716	     */
717	    private static String normalizeAddress(String address) {
718	        if (address == null) {
719	            return "";
720	        }
721	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
722	        if (collapsed.isEmpty()) {
723	            return "";
724	        }
725	        String[] tokens = collapsed.split(" ");
726	        StringBuilder sb = new StringBuilder();
727	        for (String token : tokens) {
728	            String expanded = switch (token) {
729	                case "ST" -> "STREET";
730	                case "RD" -> "ROAD";
731	                case "AVE" -> "AVENUE";
732	                default -> token;
733	            };
734	            if (sb.length() > 0) {
735	                sb.append(' ');
736	            }
737	            sb.append(expanded);
738	        }
739	        return sb.toString();
740	    }
741	
742	    /**
743	     * Derives the stable household identifier for an owner from its last name and postcode as the
744	     * upper-cased first 12 hex characters of the SHA-256 digest of
745	     * {@code normalizedLastName + '|' + postcode}, where the last name is normalized (trimmed,
746	     * internal whitespace collapsed, lower-cased) so casing and spacing do not affect it. Because the
747	     * identifier is a deterministic function of the normalized last name and postcode, owners that
748	     * share a last name and postcode share the identifier automatically — no back-fill or opt-in is
749	     * required. Returns {@code null} when no postcode is present, since the household is keyed on the
750	     * postcode and there is then nothing to key on.
751	     *
752	     * @param lastName the owner's last name (already validated non-blank)
753	     * @param postcode the owner's postcode (a validated 4-digit value, or {@code null} when absent)
754	     * @return the 12-hex-character household identifier, or {@code null} when no postcode is present
755	     */
756	    private static String householdIdFor(String lastName, String postcode) {
757	        if (postcode == null || postcode.isBlank()) {
758	            return null;
759	        }
760	        String normalizedLastName = normalizeForHousehold(lastName);
761	        try {
762	            byte[] digest = MessageDigest.getInstance("SHA-256")
763	                .digest((normalizedLastName + "|" + postcode).getBytes(StandardCharsets.UTF_8));
764	            StringBuilder sb = new StringBuilder();
765	            for (byte b : digest) {
766	                sb.append(String.format("%02X", b));
767	            }
768	            return sb.substring(0, 12);
769	        }
770	        catch (NoSuchAlgorithmException e) {
771	            throw new IllegalStateException("SHA-256 not available", e);
772	        }
773	    }
774	}
