275	    /**
276	     * Returns the owner's numeric membership level, derived from its membership points: level
277	     * {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
278	     * {@code 4} for {@code 6} or more. As with {@link #toMembershipPoints(Owner)}, the household size
279	     * is not observable here and is treated as a single member.
280	     */
281	    @Named("toMembershipLevel")
282	    default Integer toMembershipLevel(Owner owner) {
283	        if (owner == null) {
284	            return null;
285	        }
286	        return membershipLevelFor(membershipPointsFor(owner, 1));
287	    }
288	
289	    /**
290	     * Computes an owner's membership points from the given household size: starts at {@code 0}, plus
291	     * {@code 2} when a non-blank email is present, plus {@code 1} when the owner has no namesakes
292	     * ({@code namesakeCount} is 0), plus {@code 2} when {@code householdSize} is {@code 3} or more,
293	     * plus {@code 3} for tenure of more than {@code 365} days since the {@code registrationDate}.
294	     *
295	     * @param owner the owner whose points are computed, never {@code null}
296	     * @param householdSize the number of owners sharing the owner's household
297	     * @return the owner's membership points
298	     */
299	    static int membershipPointsFor(Owner owner, int householdSize) {
300	        int points = 0;
301	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
302	        if (hasEmail) {
303	            points += 2;
304	        }
305	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
306	        if (noNamesakes) {
307	            points += 1;
308	        }
309	        if (householdSize >= 3) {
310	            points += 2;
311	        }
312	        boolean tenured = owner.getRegistrationDate() != null
313	            && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365;
314	        if (tenured) {
315	            points += 3;
316	        }
317	        return points;
318	    }
319	
320	    /**
321	     * Maps membership points to the numeric membership level: level {@code 1} for {@code 0-1} points,
322	     * {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more.
323	     *
324	     * @param points the owner's membership points
325	     * @return the corresponding membership level (1-4)
326	     */
327	    static int membershipLevelFor(int points) {
328	        if (points <= 1) {
329	            return 1;
330	        }
331	        if (points <= 3) {
332	            return 2;
333	        }
334	        if (points <= 5) {
335	            return 3;
336	        }
337	        return 4;
338	    }
339	
340	    /**
341	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
342	     * contained in the owner's {@code customerCode}. Returns {@code null} when the customer code is
343	     * absent.
344	     */
345	    @Named("toCheckDigit")
346	    default Integer toCheckDigit(Owner owner) {
347	        if (owner == null || owner.getCustomerCode() == null) {
348	            return null;
349	        }
350	        int sum = 0;
351	        boolean dbl = true;
352	        String code = owner.getCustomerCode();
353	        for (int i = code.length() - 1; i >= 0; i--) {
354	            char c = code.charAt(i);
355	            if (c < '0' || c > '9') {
356	                continue;
357	            }
358	            int d = c - '0';
359	            if (dbl) {
360	                d *= 2;
361	                if (d > 9) {
362	                    d -= 9;
363	                }
364	            }
365	            sum += d;
366	            dbl = !dbl;
367	        }
368	        return (10 - (sum % 10)) % 10;
369	    }
370	
371	    private static String initial(String name) {
372	        if (name == null || name.isEmpty()) {
373	            return "";
374	        }
375	        return Character.toUpperCase(name.charAt(0)) + ".";
376	    }
377	
378	    Owner toOwner(OwnerDto ownerDto);
379	
380	    @Mapping(target = "id", ignore = true)
381	    @Mapping(target = "pets", ignore = true)
382	    Owner toOwner(OwnerFieldsDto ownerDto);
383	
384	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
385	
386	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
387	
388	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
389	        OwnerPageDto ownerPageDto = new OwnerPageDto();
390	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
391	        ownerPageDto.setPage(ownerPage.getNumber());
392	        ownerPageDto.setSize(ownerPage.getSize());
393	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
394	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
395	        return ownerPageDto;
396	    }
